給定正整數二維陣列，起點為其中數值最大的點。從起點開始移動，求經過點的數值之加總。移動規則：⑴從相鄰的點（上、下、左、右）選擇一個最大的值移動；⑵走過的點不能重複。
①請完成遞迴程式與非遞迴程式（I~XI）空格，使以下 C 程式均能執行出下列結果。（22 分）path= 88, 42, 31, 18, 23, 21, 68, 36, 55, 77, 66, 63, 28, 33, 52, sum=701
②請比較遞迴與非遞迴程式記憶體空間使用狀況。（3 分）#include <stdio.h>#define maxN 30const int NV = -1;int max(int x, int y){int r = x>y？ (I) ; return r;}int findR(int m[maxN][maxN], int x, int y, int sum){int mi = max(max(m[x+1][y],m[x-1][y]),max(m[x][y+1],m[x][y-1]));sum += m[x][y];printf("%d, ", m[x][y]);m[x][y] = NV;if (mi == NV) return (II) ;if (m[x+1][y] == mi) return findR(m, (III) , sum);if (m[x-1][y] == mi) return findR(m, (IV) , sum);if (m[x][y+1] == mi) return findR(m, (V) , sum);if (m[x][y-1] == mi) return findR(m, (VI) , sum);}int findI(int m[maxN][maxN], int x, int y, int sum){while(1){int mi = max(max(m[x+1][y],m[x-1][y]),max(m[x][y+1],m[x][y-1]));sum += m[x][y];printf("%d, ", m[x][y]);m[x][y] = NV;if (mi == NV) (VII) ;else if (m[x+1][y] == mi)(VIII) ;else if (m[x-1][y] == mi)(IX) ;else if (m[x][y+1] == mi)(X) ;else(XI) ;}return sum;}int main(){int x=0, y=0, mi=NV, n=5, m=6;int map[maxN][maxN]={{NV, NV, NV, NV, NV, NV, NV},{NV, 11, 15, 23, 18, 31, NV},{NV, 31, 68, 21, 88, 42, NV},{NV, 19, 36, 52, 33, 28, NV},{NV, 12, 55, 77, 66, 63, NV},{NV, NV, NV, NV, NV, NV, NV}};// 邊界都是 NVfor (int i = 1 ; i <= n ; i++){for (int j = 1 ; j <= m ; j++){if (mi < map[i][j]){mi = map[i][j];x=i; y=j;}}}printf("path= ");printf("sum=%d\n",findR(map, x, y, 0));return 0;}

敘述統計學上中位數和平均數均為數據資料的集中趨勢，中位數是將一組數值資料由小到大排列，最中間的數值為中位數。若有奇數個資料，則取最中間的數值為中位數，例如 1, 2, 3, 3, 4, 6, 7, 7, 21 的中位數是 4；若有偶數個資料，則取最中間兩個數值的平均為中位數，例如 1, 2, 3, 3,4, 6, 7, 7, 8, 21 的中位數是（4+6）/2=5。算術平均數是將一組數值加總，除以這組數值的個數，例如 1, 2, 3, 3, 4, 6, 7, 7, 21 的算術平均數=54/9=6。以下 C++程式輸出：4, 6,0102030405060708091011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859#include <iostream>#include <algorithm>using namespace std;class Compute{public:void setData(int *, int);(I)=0;protected:int *data, d_size;};class ComputeMedian: public Compute{public:double getNum();};class ComputeMean: public Compute{public:double getNum();};void Compute::setData(int *d, int s){data = d;d_size = s;sort(data, data+d_size);}double ComputeMedian::getNum(){if ((II)==1) return data[d_size/2];else return (data[ (III) ]+data[1+d_size/2])/2.0;}double ComputeMean::getNum(){double sum=0, avg=0;for (int i=0; i<d_size; i++)sum = sum + data[i];return ((IV));}class Report {public:Report(int *d, int s){data = d;d_size = s;}void setCompute(Compute *c) { cp = c; }void report(){cp->(V);cout<<cp->getNum()<<", ";}private:int *data, d_size;Compute *cp;};int main(){int data[10] ={6, 7, 1, 21, 2, 3, 4, 3, 7};Report r(data, 9);Compute *cp1 = new ComputeMedian();Compute *cp2 = new ComputeMean();r.setCompute(cp1);r.report();r.setCompute(cp2);r.report();return 0;}
